"""Container entrypoints generated by the platform, not by Terraform."""

import base64
from pathlib import Path


def entrypoint(port: int, api_workers: int) -> list[str]:
    root = Path(__file__).parent
    startup = (root / "start.py.tmpl").read_text()
    startup = startup.replace(
        "${bootstrap}", base64.b64encode((root / "bootstrap_db.py").read_bytes()).decode()
    )
    startup = startup.replace("${port}", str(port)).replace("${api_workers}", str(api_workers))
    return ["python", "-c", startup]
